"""Build reports/stage3_summary.md from the measured Stage 3 JSON files only."""
import json
from siftvqa.config import ROOT

R = ROOT / "reports"
L = json.load(open(R / "stage3_leakage.json"))
E = json.load(open(R / "stage3_edits.json"))
S = json.load(open(R / "stage3_selection.json"))
f = lambda x: f"{x['mean']} ± {x['sd']}" if x["sd"] is not None else f"{x['mean']}"
o = ["# Stage 3 summary (pilot numbers, generated by scripts/make_stage3_summary.py)", "",
     "## Splits and leakage", "",
     f"- Sizes (scenes / questions): " + "; ".join(f"{k} {v['scenes']}/{v['questions']}" for k, v in L["split_sizes"].items()),
     f"- Held-out signature `{L['signature_overlap']['held_out_signature']}`: in train {L['signature_overlap']['held_out_in_train']}, in pool {L['signature_overlap']['held_out_in_pool']}, in test {L['signature_overlap']['held_out_in_test']} (dropped from train/pool: {L['held_out_questions_dropped_from_train_pool']}).",
     f"- Scene-group overlap between splits: {L['scene_group_overlap_counts']}.",
     f"- Exact duplicate scenes within/across splits: {L['duplicate_scenes']['exact_duplicate_scenes_within_split']}/{L['duplicate_scenes']['exact_duplicate_scenes_across_splits']}; duplicate (scene, question) pairs across splits: {L['duplicate_questions_across_splits']}. Same colour+shape multiset in several splits (info only, different layouts): {L['duplicate_scenes']['attribute_multisets_shared_across_splits_(info_only)']} of {L['duplicate_scenes']['attribute_multisets_total']}.", "",
     "| Question-only / no-image baseline (test) | seen | held-out |", "|---|---|---|"]
for k, v in L["question_only_baseline"].items():
    o.append(f"| {k} (fit on train) | {v['seen_acc_pct']}% | {v['held_out_acc_pct']}% |")
sh = L["shuffled_scene_oracle_acc_pct"]
o += [f"| shuffled-scene oracle (executor run on another test scene; model-free) | {sh['seen']}% | {sh['held_out']}% |", "",
      "These are chance-level references a model must beat. The model-based shuffled-image baseline needs the VLM (Stage 4).", "",
      "## Paired edits (test set)", "",
      f"- Paired {E['n_paired']} of {E['n_test_questions']} test questions; no valid pair: {E['n_without_valid_pair']}.",
      f"- Relevant edit changed the executor answer in {E['relevant_answer_changed']}/{E['n_paired']}; irrelevant edit kept it in {E['irrelevant_answer_same']}/{E['n_paired']}; pixel audit mismatches on edited images: {E['audit_mismatches_on_edited_images']}.",
      f"- Edit kinds: {E['edit_kinds']} (`multi` = chain of up to 4 edits, used only when no single edit changes the answer).", "",
      "## Selection arms", "",
      f"Budget {S['budget']} examples per arm, seeds {S['seeds']}, pool {S['pool_size']} questions. Pool d=1 share by template: {S['pool_d1_share_pct_by_template']}; count questions with BOTH shortcuts disagreeing: {S['pool_count_both_shortcuts_disagree_pct']}%.", ""]
for mode, d in S["modes"].items():
    ag = d["aggregate_over_seeds"]
    o += [f"### exists_mode = `{mode}`", "", "d=1 share of selected examples, % (mean ± sd over seeds)", "",
          "| Arm | count_cs | exists_cs | compare_shape | count+exists | all examples | overlap with shortcut arm |", "|---|---|---|---|---|---|---|"]
    for a, v in ag.items():
        bt = v["by_template"]
        o.append(f"| {a} | {f(bt['count_cs']['d1_share_pct'])} | {f(bt['exists_cs']['d1_share_pct'])} | {f(bt['compare_shape']['d1_share_pct'])} | {f(v['d1_share_count_exists_pct'])} | {f(v['d1_share_all_pct'])} | {f(v['overlap_with_shortcut_arm'])} |")
    sa, mr = ag["shortcut_aware"], ag["matched_random"]
    o += ["", f"Contrast shortcut-aware minus matched random: count {sa['by_template']['count_cs']['d1_share_pct']['mean'] - mr['by_template']['count_cs']['d1_share_pct']['mean']:.1f} pts, exists {sa['by_template']['exists_cs']['d1_share_pct']['mean'] - mr['by_template']['exists_cs']['d1_share_pct']['mean']:.1f} pts, count+exists {sa['d1_share_count_exists_pct']['mean'] - mr['d1_share_count_exists_pct']['mean']:.1f} pts.", "",
          "Real label mix per arm (seed 0; answer counts per template):", "", "| Arm | count_cs answers | exists_cs answers | compare_shape answers |", "|---|---|---|---|"]
    for a, v in d["seed0_detail"].items():
        if a == "checks":
            continue
        bt = v["by_template"]
        o.append(f"| {a} | {bt['count_cs']['answers']} | {bt['exists_cs']['answers']} | {bt['compare_shape']['answers']} |")
    c = d["checks_all_seeds"]
    o += ["", "Checks over all seeds: " + ", ".join(f"{k}={all(x[k] for x in c)}" for k in ("matched_random_label_counts_identical_to_shortcut_arm", "difficulty_label_counts_identical", "diversity_label_counts_identical", "matched_random_bucket_counts_identical", "shared_base_identical_in_all_arms", "all_count_examples_in_shortcut_arm_are_d1")) + f"; shortfalls: {[x['shortcut_arm_info'] for x in c]}.", "",
          "Mean objects per count example: " + ", ".join(f"{a} {v['by_template']['count_cs']['mean_n_objects']['mean']}" for a, v in ag.items()) + ".", ""]
w = S["weak_contrast_diagnostics"]
A = w["count_arms_mean_over_seeds"]
o += ["## How different is the shortcut arm from random? (count_cs, measured)", "",
      "| count_cs examples | d=1 % | both shortcuts disagree % | mean # disagreeing shortcuts | mean abs gap (intended vs shortcut) | mean objects |", "|---|---|---|---|---|---|"]
for k, v in A.items():
    o.append(f"| {k} | {v['d1_pct']} | {v['both_disagree_pct']} | {v['mean_n_disagreeing']} | {v['mean_abs_gap']} | {v['mean_n_objects']} |")
o += ["", f"Strict d (both count shortcuts disagree) exists for only {w['strict_d_both_shortcuts_disagree']['pool_n']} of {w['count_pool_n']} pool count questions ({w['strict_d_both_shortcuts_disagree']['pool_share_pct']}%); at this budget and label quota it would be short by about {w['strict_d_would_be_short_by_examples_per_seed_(sum over answer cells)']} examples per seed.", ""]
(R / "stage3_summary.md").write_text("\n".join(o) + "\n")
print("\n".join(o))
